M1 = "Introduction, Solar System & Global Tectonics"
M2 = "Crystallography & Mineralogy"
M3 = "Petrology: Igneous, Sedimentary & Metamorphic Rocks"

SETS = []


def Q(prompt, right, wrongs, pos, expl, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """Multiple choice with the correct option inserted at index `pos` (0 = A ... 3 = D)."""
    choices = [C(t, why=w) for t, w in wrongs]
    choices.insert(pos, C(right, correct=True))
    return MC(prompt, choices, steps=[S("Reasoning", text=expl)], concept=concept, skill=skill, hint=hint,
              feedback=feedback, diagram=diagram, diagram_alt=diagram_alt)


